def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def append(file,rows):
    p=ROOT/file; old=p.read_bytes()
    ids={json.loads(x).get('id') for x in old.splitlines() if x.strip()}
    assert all(x['id'] not in ids for x in rows)
    payload=(b'\n' if old and not old.endswith(b'\n') else b'')+''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in rows).encode('utf-8')
    with p.open('ab') as f:f.write(payload)
def once(text,old,new):
    assert text.count(old)==1,repr(old[:180])
    return text.replace(old,new,1)
def section(text,start,end,content):
    assert text.count(start)==1 and text.count(end)==1
    a=text.index(start);b=text.index(end,a)
    return text[:a]+content.rstrip()+'\n\n'+text[b:]
def global_claims(text):
    return text.replace('C-007','C-015').replace('C-012','C-016')

